import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import "./App.css";
import Menu2 from "./components/Menu2";
import Form from "./components/Form";
import Navbar from "./components/Navbar";
import Table from "./components/Table";
import History from "./components/History";
import FinalArea from "./components/FinalArea";
import RssTable from "./pages/RssTable";
import Home from "./pages/Home";

function App() {
  return (
    <Router>
      <div className="bg-gray-50 min-h-screen">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/rss" element={<RssTable/>} />
          <Route path="/top" element={<Menu2 Name="TOP" />} />
          <Route path="/pnr-overhead-summary" element={<Menu2 Name="Pnr Overhead Summary" />} />
          <Route path="/history" element={<History />} />
        </Routes>
        {/* Menu Section with Full-Width Buttons */}
        <div className="w-full h-1">
          <div className="w-full bg-white shadow-md rounded-lg py-2 border">
            <div className="flex justify-between w-full">
              <Link to="/rss" className="px-20 ml-1 py-4 bg-gradient-to-r from-blue-600 to-indigo-700 text-white font-semibold rounded-lg shadow-md hover:scale-105 transition-transform duration-200">RSS</Link>
              <Link to="/top" className="px-20 py-4 bg-gradient-to-r from-blue-600 to-indigo-700 text-white font-semibold rounded-lg shadow-md hover:scale-105 transition-transform duration-200">TOP</Link>
              <Link to="/pnr-overhead-summary" className="px-20 py-4 bg-gradient-to-r from-blue-600 to-indigo-700 text-white font-semibold rounded-lg shadow-md hover:scale-105 transition-transform duration-200">Pnr Overhead Summary</Link>
              <Link to="/history" className="px-20 mr-3 py-4 bg-gradient-to-r from-blue-600 to-indigo-700 text-white font-semibold rounded-lg shadow-md hover:scale-105 transition-transform duration-200">History</Link>
            </div>
          </div>
        </div>

      </div>
    </Router>
  );
}

export default App;
